1	package darksafe
2	
3	import (
4		"reflect"
5		"strconv"
6		"strings"
7		"testing"
8	)
9	
10	// batchSizeDoc builds a plan document with three available clusters and no
11	// spreadBy; size is substituted as the raw JSON integer literal.
12	func batchSizeDoc(size string) string {
13		return `{"app":"app","revision":"r1","image":"img","batchSize":` + size +
14			`,"clusters":[{"id":"c1"},{"id":"c2"},{"id":"c3"}]}`
15	}
16	
17	// A batchSize literal must be kept exactly as written whenever the running
18	// environment's Go int can represent it, and rejected with the field error —
19	// never narrowed — when it cannot. The boundary therefore follows the actual
20	// integer width rather than one hard-coded 32-bit ceiling: on a 32-bit
21	// environment 2147483647 is the largest legal value and
22	// 2147483648/4294967297 are configuration errors; on a 64-bit environment
23	// those same values plan normally, up to the largest positive int itself.
24	func TestParse_BatchSizeNativeIntBoundary(t *testing.T) {
25		// 2147483647 is legal in every supported environment and keeps its value.
26		in, err := ParseReleaseInput([]byte(batchSizeDoc("2147483647")))
27		if err != nil {
28			t.Fatalf("2147483647 must be representable everywhere, got %v", err)
29		}
30		if in.BatchSize != 2147483647 {
31			t.Fatalf("batchSize = %d, want 2147483647", in.BatchSize)
32		}
33	
34		// The largest positive int of this environment is legal and preserved.
35		maxInt := int(^uint(0) >> 1)
36		in, err = ParseReleaseInput([]byte(batchSizeDoc(strconv.Itoa(maxInt))))
37		if err != nil {
38			t.Fatalf("max int %d must be legal, got %v", maxInt, err)
39		}
40		if in.BatchSize != maxInt {
41			t.Fatalf("batchSize = %d, want %d", in.BatchSize, maxInt)
42		}
43	
44		switch strconv.IntSize {
45		case 32:
46			// Values beyond the 32-bit ceiling are all configuration errors, even
47			// though they narrow into other ints: 4294967297 would silently
48			// become 1 and 2147483648 a negative number. Neither may plan.
49			for _, lit := range []string{"2147483648", "4294967297"} {
50				zero, perr := ParseReleaseInput([]byte(batchSizeDoc(lit)))
51				if perr == nil {
52					t.Fatalf("batchSize %s must be rejected on a 32-bit environment, got %+v", lit, zero)
53				}
54				if want := `字段 "batchSize" 必须是正整数`; perr.Error() != want {
55					t.Fatalf("batchSize %s: error = %q, want %q", lit, perr.Error(), want)
56				}
57				if strings.Contains(perr.Error(), "JSON 格式错误") {
58					t.Fatalf("batchSize %s is a legal JSON number, not a format error: %v", lit, perr)
59				}
60				if !reflect.DeepEqual(zero, ReleasePlanInput{}) {
61					t.Fatalf("rejected parse must return the zero-value config, got %+v", zero)
62				}
63			}
64		case 64:
65			// The exact values the 32-bit environment cannot hold stay usable here
66			// with their written values; the fix must not clamp every environment
67			// to the 32-bit ceiling.
68			for _, lit := range []string{"2147483648", "4294967297"} {
69				wide, perr := ParseReleaseInput([]byte(batchSizeDoc(lit)))
70				if perr != nil {
71					t.Fatalf("batchSize %s must be legal on a 64-bit environment, got %v", lit, perr)
72				}
73				want, _ := strconv.ParseInt(lit, 10, 64)
74				if int64(wide.BatchSize) != want {
75					t.Fatalf("batchSize = %d, want %s (must not be truncated or clamped)", wide.BatchSize, lit)
76				}
77			}
78		default:
79			t.Fatalf("unexpected int size %d", strconv.IntSize)
80		}
81	}
82	
83	// Through the public parse entry an out-of-range capacity fails before any
84	// filtering or batching: the returned config is the zero value and the cause
85	// is the existing field error. On a 32-bit environment the document carrying
86	// 4294967297 and three available clusters previously narrowed to batchSize 1
87	// and produced three single-cluster batches; now nothing is planned.
88	func TestParse_BatchSizeOutOfRangePlansNothing(t *testing.T) {
89		if strconv.IntSize != 32 {
90			// 4294967297 overflows only on a 32-bit int; the 64-bit preservation
91			// contract is covered by TestParse_BatchSizeNativeIntBoundary.
92			return
93		}
94		in, err := ParseReleaseInput([]byte(batchSizeDoc("4294967297")))
95		if err == nil {
96			t.Fatalf("4294967297 must be rejected on a 32-bit environment, got %+v", in)
97		}
98		if want := `字段 "batchSize" 必须是正整数`; err.Error() != want {
99			t.Fatalf("error = %q, want %q", err.Error(), want)
100		}
101		if !reflect.DeepEqual(in, ReleasePlanInput{}) {
102			t.Fatalf("expected the zero-value config on rejection, got %+v", in)
103		}
104		// The zero-value config never reaches batching (it fails field validation
105		// on app before batchSize); in particular there is no plan whose three
106		// single-cluster batches would reveal the narrowed value 1.
107		if plan, perr := MakeReleasePlan(in); perr == nil {
108			t.Fatalf("planning the rejected config must fail, got %+v", plan)
109		}
110	}
111	
112	// CLI contract at the integer-width boundary. On a 32-bit environment the
113	// document with batchSize 4294967297 and three available clusters must exit
114	// 1 with empty stdout and the field error on stderr — it must not print three
115	// single-cluster batches as if batchSize were 1. On a 64-bit environment the
116	// same document plans normally: one batch holding all three clusters.
117	func TestPlanCLI_BatchSizeNativeIntBoundary(t *testing.T) {
118		code, stdout, stderr := runCLI(t, "plan", writePlanDoc(t, batchSizeDoc("4294967297")))
119		switch strconv.IntSize {
120		case 32:
121			if code != 1 {
122				t.Fatalf("expected exit 1, got %d; stdout=%q stderr=%q", code, stdout, stderr)
123			}
124			if stdout != "" {
125				t.Fatalf("stdout must be empty on rejection, got %q", stdout)
126			}
127			if want := `字段 "batchSize" 必须是正整数`; !strings.Contains(stderr, want) {
128				t.Fatalf("stderr = %q, want it to contain %q", stderr, want)
129			}
130			if strings.Contains(stderr, "JSON 格式错误") {
131				t.Fatalf("4294967297 is a legal JSON number, stderr must not call it malformed: %q", stderr)
132			}
133		case 64:
134			if code != 0 {
135				t.Fatalf("expected exit 0, got %d; stderr=%q", code, stderr)
136			}
137			if stderr != "" {
138				t.Fatalf("unexpected stderr: %q", stderr)
139			}
140			p := decodeCLIPlan(t, stdout)
141			if len(p.Batches) != 1 ||
142				strings.Join(p.Batches[0].Clusters, ",") != "c1,c2,c3" {
143				t.Fatalf("expected one batch [c1 c2 c3], got %+v", p.Batches)
144			}
145		}
146	}
147	
148	// A capacity within native int range is still only an upper bound per batch:
149	// enabling fault-domain spreading keeps same-domain clusters in separate
150	// batches even when the capacity is 4294967297 (a value legal only where the
151	// native int can hold it).
152	func TestPlan_BatchSizeBoundaryStillRespectsSpreadBy(t *testing.T) {
153		lit := "4294967297"
154		if strconv.IntSize == 32 {
155			// Use the largest value this environment can represent; the spreadBy
156			// guarantee must hold at the ceiling regardless of int width.
157			lit = "2147483647"
158		}
159		raw := `{"app":"app","revision":"r1","image":"img","batchSize":` + lit + `,"spreadBy":"zone",` +
160			`"clusters":[` +
161			`{"id":"c1","tags":{"zone":"east"}},` +
162			`{"id":"c2","tags":{"zone":"east"}},` +
163			`{"id":"c3","tags":{"zone":"east"}}]}`
164		in := parsePlan(t, raw)
165		plan, err := MakeReleasePlan(in)
166		if err != nil {
167			t.Fatal(err)
168		}
169		if got := batchIDs(plan); strings.Join(got, "|") != "c1|c2|c3" {
170			t.Fatalf("huge in-range capacity must not merge one domain into a batch, got %v", got)
171		}
172	}
