			name: "surrogate before malformed number in the same object",
			body: base + `,"meta":{"note":"\uD800","n":1E+}`,
			kind: "surrogate", path: "$.meta.note",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
