// nil-vs-empty slice distinctions beyond the fields set.
func (in ReleasePlanInput) equal(other ReleasePlanInput) bool {
	if in.App != other.App || in.Revision != other.Revision || in.Image != other.Image ||
		in.BatchSize != other.BatchSize || in.SpreadBy != other.SpreadBy {
		return false
	}
